#[tokio::main]
async fn main() -> ResultWithDefaultError<()> {
    // Auto-load repo-local .env for local development without manual shell sourcing.
    // This ensures `cargo run` uses fake/test credentials instead of falling through
    // to macOS keychain-backed storage.
    let _ = dotenvy::from_filename_override(".env");
    let parsed_args = match Cli::try_parse() {
        Ok(cli) => cli,
        Err(err) => {
            if err.kind() == ErrorKind::InvalidSubcommand {
                let mut msg = err.to_string();
                msg.push_str("\nAvailable commands: auth, entry, project, tag, client, task, workspace, org, me, preferences, report, config, logout\n");
                eprint!("{msg}");
                std::process::exit(2);
            }
            // For all other errors (--help, --version, missing args, etc.), use clap's default handling
            err.exit();
        }
    };
    let json_mode = parsed_args.cmd.has_json_flag();
    match execute_subcommand(parsed_args).await {
        Ok(()) => Ok(()),
        Err(error) => {
            if json_mode {
                let msg = format!("{error}");
                let msg = msg.trim_end_matches('\n');
                let escaped = msg
                    .replace('\\', "\\\\")
                    .replace('"', "\\\"")
                    .replace('\n', "\\n");
                eprint!("{{\"error\":\"{escaped}\"}}");
            } else {
                eprint!("{error}");
            }
            std::process::exit(1);
        }
    }
}

async fn execute_subcommand(args: Cli) -> ResultWithDefaultError<()> {
    setup_working_directory(args.directory)?;

    let picker = picker::get_picker(false);

    match args.cmd {
        Command::Auth {
            action,
            api_token,
            api_type,
            api_url,
        } => match action {
            Some(AuthAction::Status { json }) => {
                let status = AuthStatusCommand::get_status();
                if json {
                    AuthStatusCommand::execute_json(io::stdout(), status)
                } else {
                    AuthStatusCommand::execute(io::stdout(), status)
                }
            }
            Some(AuthAction::Login {

            let days_since_monday = today.weekday().num_days_from_monday();
            let last_monday = today - chrono::Duration::days((days_since_monday + 7) as i64);
            let naive = last_monday.and_hms_opt(0, 0, 0).unwrap();
            return match Local.from_local_datetime(&naive) {
                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            };
        }
        _ => {}
    }

    if let Ok(parsed) = DateTime::parse_from_rfc3339(value) {
        return Ok(parsed.with_timezone(&Utc));
    }

    let local_formats = [
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%dT%H:%M",
    ];

    for format in local_formats {
        if let Ok(naive) = NaiveDateTime::parse_from_str(value, format) {
            return match Local.from_local_datetime(&naive) {
                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            };
        }
    }

    if let Ok(date) = NaiveDate::parse_from_str(value, "%Y-%m-%d") {
        let naive = match date.and_hms_opt(0, 0, 0) {
            Some(naive) => naive,
            None => return Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
        };
        return match Local.from_local_datetime(&naive) {
            LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
            _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
        };
    }

    // Time-only formats: HH:MM or HH:MM:SS (interpreted as today in local time)
    let time_formats = ["%H:%M:%S", "%H:%M"];
    for format in time_formats {
        if let Ok(time) = NaiveTime::parse_from_str(value, format) {
            let today = Local::now().date_naive();
            let naive = NaiveDateTime::new(today, time);
            return match Local.from_local_datetime(&naive) {
                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            };
        }
    }

    Err(Box::new(ArgumentError::InvalidDateTime(input.to_string())))
}

/// Like `parse_datetime_input`, but time-only values (HH:MM, HH:MM:SS) are
/// interpreted relative to `reference_date` instead of today.
pub fn parse_datetime_input_with_reference(
    input: &str,
    reference_date: NaiveDate,
) -> ResultWithDefaultError<DateTime<Utc>> {
    let value = input.trim();

    // Time-only formats: use reference_date instead of today
    let time_formats = ["%H:%M:%S", "%H:%M"];
    for format in time_formats {
        if let Ok(time) = NaiveTime::parse_from_str(value, format) {
            let naive = NaiveDateTime::new(reference_date, time);
            return match Local.from_local_datetime(&naive) {
                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            };
        }
    }

    // Fall back to the standard parser for all other formats
    parse_datetime_input(input)
}

