use std::collections::BTreeMap;
use std::io::{self, Write};

use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;

pub struct InvoiceMonthlyCommand;

/// The invoice rule is based on completed billable entries only. Running
/// entries have a negative duration sentinel and are never invoiceable.
fn invoice_seconds(entry: &TimeEntry) -> Option<i64> {
    if entry.billable && entry.stop.is_some() && entry.duration >= 0 {
        Some(entry.duration)
    } else {
        None
    }
}

fn monthly_totals(entries: impl IntoIterator<Item = TimeEntry>) -> BTreeMap<String, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries {
        if let Some(seconds) = invoice_seconds(&entry) {
            let month = entry.start.format("%Y-%m").to_string();
            *totals.entry(month).or_insert(0) += seconds;
        }
    }
    totals
}

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = monthly_totals(entries);
        let mut output = io::BufWriter::new(io::stdout().lock());

        if totals.is_empty() {
            writeln!(output, "(no data)")
                .map_err(|error| Box::new(error) as Box<dyn std::error::Error + Send>)?;
            return Ok(());
        }

        let total: i64 = totals.values().sum();
        for (month, seconds) in totals {
            writeln!(output, "{month}  {seconds}s")
                .map_err(|error| Box::new(error) as Box<dyn std::error::Error + Send>)?;
        }
        writeln!(output, "Total  {total}s")
            .map_err(|error| Box::new(error) as Box<dyn std::error::Error + Send>)?;
        Ok(())
    }
}

